(5840377, 849732, 1569, '<td valign="top">The people standing around arent interesting,crop them out and concentrate on the graffiti.There probably is more than you show in this pix.</td>', 'The people standing around arent interesting,crop them out and concentrate on the graffiti.There probably is more than you show in this pix.', '2010-01-28 12:03:15.000000', NULL, 1),
(5840382, 850114, 1569, '<td valign="top">The left half of this one needs to be cropped out. Consentrate on the graffiti, and remove the top and bottom black bars or make them narrower.</td>', 'The left half of this one needs to be cropped out. Consentrate on the graffiti, and remove the top and bottom black bars or make them narrower.', '2010-01-28 12:05:59.000000', NULL, 1),
(5840385, 849905, 87252, '<td valign="top">Sweet shot, looks like you nearly took out your camera!</td>', 'Sweet shot, looks like you nearly took out your camera!', '2010-01-28 12:06:17.000000', NULL, 1),
