(5840502, 850146, 87252, '<td valign="top">Nice colours and funny title, good texture on the wall.</td>', 'Nice colours and funny title, good texture on the wall.', '2010-01-28 12:42:18.000000', NULL, 1),
(5840509, 849880, 87252, '<td valign="top">Wow some of these guys are multi talented; artists AND mountain climbers. I love the texture on the wall, the BW conversion has some really nice subtle silvery tones. Bet this would look awesome blown up in a massive print.</td>', 'Wow some of these guys are multi talented; artists AND mountain climbers. I love the texture on the wall, the BW conversion has some really nice subtle silvery tones. Bet this would look awesome blown up in a massive print.', '2010-01-28 12:45:11.000000', NULL, 1),
(5840514, 848867, 87252, '<td valign="top">Great composition, I like the colour contrast between the silvery trees and the brown of the leaves on the floor. Texture is also great, just the right amount of sharpening.</td>', 'Great composition, I like the colour contrast between the silvery trees and the brown of the leaves on the floor. Texture is also great, just the right amount of sharpening.', '2010-01-28 12:46:37.000000', NULL, 1),
(5840681, 850063, 109414, '<td valign="top">love the idea!!  mostly cuz i believe the lochness is real but i think the follow through couldve been alot better, maybe crop in alittle closer!</td>', 'love the idea!!  mostly cuz i believe the lochness is real but i think the follow through couldve been alot better, maybe crop in alittle closer!', '2010-01-28 14:21:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5840699, 848969, 109414, '<td valign="top">So Beautiful.....8</td>', 'So Beautiful.....8', '2010-01-28 14:30:22.000000', NULL, 1),
(5840734, 849790, 87252, '<td valign="top">Nice graffiti, I think the composition could have been better a fraction of a second later when the man''s bag was fully in the frame.</td>', 'Nice graffiti, I think the composition could have been better a fraction of a second later when the man''s bag was fully in the frame.', '2010-01-28 14:45:51.000000', NULL, 1),
(5840739, 850108, 87252, '<td valign="top">Hmmm I''m having real trouble getting the "graffiti" part of this, however I absolutely love the shot, fantastic DOF and extremely symbolic. So I''m going to give you a DNMC and a fave!</td>', 'Hmmm I''m having real trouble getting the "graffiti" part of this, however I absolutely love the shot, fantastic DOF and extremely symbolic. So I''m going to give you a DNMC and a fave!', '2010-01-28 14:48:34.000000', NULL, 1),
(5840744, 849509, 87252, '<td valign="top">Cool contrast of structures and colours, I might have gone for a crop to take out the top of the tower and the bottom left corner personally.</td>', 'Cool contrast of structures and colours, I might have gone for a crop to take out the top of the tower and the bottom left corner personally.', '2010-01-28 14:50:51.000000', NULL, 1),
(5840746, 849536, 87252, '<td valign="top">Very nice, graffiti''s natural environment. I like the silhouette but a flash-filled subject might have scored better.</td>', 'Very nice, graffiti''s natural environment. I like the silhouette but a flash-filled subject might have scored better.', '2010-01-28 14:51:59.000000', NULL, 1),
(5840749, 849751, 87252, '<td valign="top">Wow this looks like a modern art installation in a really trendy gallery. Nice one.</td>', 'Wow this looks like a modern art installation in a really trendy gallery. Nice one.', '2010-01-28 14:53:24.000000', NULL, 1),
(5840750, 850178, 87252, '<td valign="top">Love the colours and composition.</td>', 'Love the colours and composition.', '2010-01-28 14:54:30.000000', NULL, 1),
(5840765, 850172, 87252, '<td valign="top">I really like the idea, great model, lovely execution and light. My only gripe here would be composition, I think that given the subject isn''t going to jump any higher than the wall perhaps you could have left the sky out. It is dramatic and well exposed but it seems slightly superfluous and potentially distracting, especially given there is an electricity pylon sticking up into it. Overall I like the shot though.</td>', 'I really like the idea, great model, lovely execution and light. My only gripe here would be composition, I think that given the subject isn''t going to jump any higher than the wall perhaps you could have left the sky out. It is dramatic and well exposed but it seems slightly superfluous and potentially distracting, especially given there is an electricity pylon sticking up into it. Overall I like the shot though.', '2010-01-28 15:03:05.000000', NULL, 1),
(5840773, 849745, 87252, '<td valign="top">Wow this makes me feel slightly queezy. Nice shot.</td>', 'Wow this makes me feel slightly queezy. Nice shot.', '2010-01-28 15:04:59.000000', NULL, 1),
(5840774, 848517, 87252, '<td valign="top">Love it.</td>', 'Love it.', '2010-01-28 15:05:31.000000', NULL, 1),
(5840776, 850113, 87252, '<td valign="top">Ah ha! It seems there was a DPC team in action this day. I have to say I prefer this one, fewer distracting elements and I like the way the basketball dude seems to be checking out the dancer''s shoes. Having second thoughts perhaps about his choice of physical activity?</td>', 'Ah ha! It seems there was a DPC team in action this day. I have to say I prefer this one, fewer distracting elements and I like the way the basketball dude seems to be checking out the dancer''s shoes. Having second thoughts perhaps about his choice of physical activity?', '2010-01-28 15:09:44.000000', NULL, 1),
(5840780, 849895, 87252, '<td valign="top">Wow that''s epic, man if this doesn''t come in the top 10 I''ll feel for you. Great control of the exposure in the windows. Minor gripe that the back wheel of the bike is a bit chopped off, very minor though.</td>', 'Wow that''s epic, man if this doesn''t come in the top 10 I''ll feel for you. Great control of the exposure in the windows. Minor gripe that the back wheel of the bike is a bit chopped off, very minor though.', '2010-01-28 15:12:13.000000', NULL, 1),
(5840783, 850075, 87252, '<td valign="top">Cool, best train shot in the challenge I think.</td>', 'Cool, best train shot in the challenge I think.', '2010-01-28 15:12:50.000000', NULL, 1),
(5840784, 848767, 87252, '<td valign="top">Sweet composition and great colour range. Nicely seen.</td>', 'Sweet composition and great colour range. Nicely seen.', '2010-01-28 15:14:24.000000', NULL, 1),
(5840788, 849939, 87252, '<td valign="top">Cool shot - I can see you though! Perhaps the little skater man could have been a bit more towards the left-hand third.</td>', 'Cool shot - I can see you though! Perhaps the little skater man could have been a bit more towards the left-hand third.', '2010-01-28 15:18:25.000000', NULL, 1),
(5840924, 850084, 66038, '<td valign="top">Nothing about this really works for me. There is no dimension, it''s not sharp,the grafitti is contrived... it just falls flat.</td>', 'Nothing about this really works for me. There is no dimension, it''s not sharp,the grafitti is contrived... it just falls flat.', '2010-01-28 15:59:19.000000', NULL, 1),
(5841137, 849686, 103922, '<td valign="top">Not basic editing</td>', 'Not basic editing', '2010-01-28 16:58:58.000000', NULL, 1),
(5841140, 849901, 91197, '<td valign="top"><strike>The fish eye effect fits well in this one. But the overall impression is in a way not that interesting imo!</strike> <br/> <br/>Well it seems I ll have to revise my first judgment about this shot. It s a great shot and a very interesting one.</td>', 'The fish eye effect fits well in this one. But the overall impression is in a way not that interesting imo!  Well it seems I ll have to revise my first judgment about this shot. It s a great shot and a very interesting one.', '2010-01-28 16:59:56.000000', NULL, 1),
(5841145, 849099, 91197, '<td valign="top">Something is missing from this scene imo. Pretty nice shot though! 7</td>', 'Something is missing from this scene imo. Pretty nice shot though! 7', '2010-01-28 17:02:57.000000', NULL, 1),
(5841251, 848836, 112107, '<td valign="top">6* for the colors.</td>', '6* for the colors.', '2010-01-28 18:02:34.000000', NULL, 1),
(5841254, 850155, 112107, '<td valign="top">Great perspective but ackward border.It competes with the subject.</td>', 'Great perspective but ackward border.It competes with the subject.', '2010-01-28 18:04:00.000000', NULL, 1),
(5841256, 849790, 112107, '<td valign="top">Fantastic grafitti, great colors but needless passerby. The border isn''t helping.<br/>I''m divided.</td>', 'Fantastic grafitti, great colors but needless passerby. The border isn''t helping.I''m divided.', '2010-01-28 18:05:49.000000', NULL, 1),
(5841258, 848956, 112107, '<td valign="top">Interesting picture but B&amp;W doesn''t suit it IMHO. I wonder how lighting affected that choice.</td>', 'Interesting picture but B&W doesn''t suit it IMHO. I wonder how lighting affected that choice.', '2010-01-28 18:07:20.000000', NULL, 1),
(5841260, 850116, 112107, '<td valign="top">Great use of the border! Great subject also, but I just fell the colors are a bit flat.<br/>7*</td>', 'Great use of the border! Great subject also, but I just fell the colors are a bit flat.7*', '2010-01-28 18:08:53.000000', NULL, 1),
(5841286, 849811, 112107, '<td valign="top">Fantastic contrast between color and greys. Great converging lines, I just feel the picture would be perfect if vanishing point wasn''t so close to the edge.<br/>8*</td>', 'Fantastic contrast between color and greys. Great converging lines, I just feel the picture would be perfect if vanishing point wasn''t so close to the edge.8*', '2010-01-28 18:31:46.000000', NULL, 1),
(5841304, 850172, 112107, '<td valign="top">Great implied lines, great colors (except for the sky) and I believe this could be heavily improved with a much tighter crop leaving very little of it.<br/>7*</td>', 'Great implied lines, great colors (except for the sky) and I believe this could be heavily improved with a much tighter crop leaving very little of it.7*', '2010-01-28 18:37:38.000000', NULL, 1),
(5841338, 850120, 112107, '<td valign="top">Incredible colors and contrast. Would have been a 10* had you removed the distortion and cropped along the upper bricks.</td>', 'Incredible colors and contrast. Would have been a 10* had you removed the distortion and cropped along the upper bricks.', '2010-01-28 18:40:30.000000', NULL, 1),
(5841342, 850095, 112107, '<td valign="top">Good colors.</td>', 'Good colors.', '2010-01-28 18:41:00.000000', NULL, 1),
(5841347, 849536, 112107, '<td valign="top">Great energy on those lines. The exposure is just right.<br/>8*</td>', 'Great energy on those lines. The exposure is just right.8*', '2010-01-28 18:42:30.000000', NULL, 1),
(5841350, 849895, 112107, '<td valign="top">9*.<br/>This is one full of all kind of beautiful contrasts.<br/>The distortion alone is keeping me from giving it a 10.<br/><br/><i>Message edited by author 2010-02-03 03:56:36.</i></td>', '9*.This is one full of all kind of beautiful contrasts.The distortion alone is keeping me from giving it a 10.', '2010-01-28 18:45:44.000000', '2010-02-03 03:56:36.000000', 1),
(5841352, 849647, 112107, '<td valign="top">Great subject and framing. A bit unrealistic contrast (looks HDRed) and I''m really not a fan of half borders.</td>', 'Great subject and framing. A bit unrealistic contrast (looks HDRed) and I''m really not a fan of half borders.', '2010-01-28 18:48:03.000000', NULL, 1),
(5841354, 849767, 112107, '<td valign="top">Great subject. Framing is almost perfect. Exposure and contrast OTOH aren''t at the same level.</td>', 'Great subject. Framing is almost perfect. Exposure and contrast OTOH aren''t at the same level.', '2010-01-28 18:49:29.000000', NULL, 1),
(5841355, 849901, 112107, '<td valign="top">Hey! I''ve seen this already and I had a pejorative comment about distortion...<br/>Great picture but I liked the other one better.</td>', 'Hey! I''ve seen this already and I had a pejorative comment about distortion...Great picture but I liked the other one better.', '2010-01-28 18:51:53.000000', NULL, 1),
(5841357, 850097, 112107, '<td valign="top">Liked: color, processing.<br/>Didn''t like: framing, half border.</td>', 'Liked: color, processing.Didn''t like: framing, half border.', '2010-01-28 18:52:55.000000', NULL, 1),
(5841360, 849324, 112107, '<td valign="top">I''m completely clueless, what is it?</td>', 'I''m completely clueless, what is it?', '2010-01-28 18:54:02.000000', NULL, 1),
(5841364, 850130, 112107, '<td valign="top">Had you completely cropped the ground this would be a 10* for me.</td>', 'Had you completely cropped the ground this would be a 10* for me.', '2010-01-28 18:56:10.000000', NULL, 1),
(5841371, 850118, 112107, '<td valign="top">A tighter crop and better focus would make it a very strong contender.</td>', 'A tighter crop and better focus would make it a very strong contender.', '2010-01-28 19:06:27.000000', NULL, 1),
(5841372, 849880, 112107, '<td valign="top">WOW! One of my favorites. I''m divided about the border though.<br/>9*</td>', 'WOW! One of my favorites. I''m divided about the border though.9*', '2010-01-28 19:08:17.000000', NULL, 1),
