(5843840, 849848, 3032, '<td valign="top">I always piss my signature on the wall....</td>', 'I always piss my signature on the wall....', '2010-01-29 19:10:50.000000', NULL, 1),
(5844025, 849625, 97192, '<td valign="top">This image really speaks to me. The blemish in the concrete on the eye is indicative of a blemish on the human soul, being reflected in the eye (hence the name ''Window to the Soul'' I believe). The idea behind this image is absolutely brilliant; an intelligent, yet crudely refined portrayal of modern existentialism. Of course, I forgot to mention just how much of a gem this particular specimen of graffiti is!</td>', 'This image really speaks to me. The blemish in the concrete on the eye is indicative of a blemish on the human soul, being reflected in the eye (hence the name ''Window to the Soul'' I believe). The idea behind this image is absolutely brilliant; an intelligent, yet crudely refined portrayal of modern existentialism. Of course, I forgot to mention just how much of a gem this particular specimen of graffiti is!', '2010-01-29 22:44:49.000000', NULL, 1),
(5844112, 850104, 37845, '<td valign="top">The light painting is really cool, and effectively distinguishes this shots from others in the challenge.</td>', 'The light painting is really cool, and effectively distinguishes this shots from others in the challenge.', '2010-01-30 00:34:07.000000', NULL, 1),
(5844115, 849811, 37845, '<td valign="top">I really like the leading lines in this shot, and how they fade into the blowing snow.</td>', 'I really like the leading lines in this shot, and how they fade into the blowing snow.', '2010-01-30 00:34:42.000000', NULL, 1),
(5844167, 850020, 75618, '<td valign="top">The added lights really make this photo. One of my favorites in the challenge. 8</td>', 'The added lights really make this photo. One of my favorites in the challenge. 8', '2010-01-30 02:34:45.000000', NULL, 1),
(5844173, 849996, 75618, '<td valign="top">Nice find, this one stands out! The image looks a little dull/flat though. A slight boost in contrast/saturation would significantly improve it. 7</td>', 'Nice find, this one stands out! The image looks a little dull/flat though. A slight boost in contrast/saturation would significantly improve it. 7', '2010-01-30 02:40:13.000000', NULL, 1),
