(5848522, 850172, 105441, '<td valign="top">Great elements.  The "look" on the basketball player provided a great opportunity for you, but good eye to see that.  8</td>', 'Great elements.  The "look" on the basketball player provided a great opportunity for you, but good eye to see that.  8', '2010-02-02 00:18:37.000000', NULL, 1),
(5848524, 850130, 105441, '<td valign="top">Great art, but I don''t see any unique application of the photographer''s talents here.</td>', 'Great art, but I don''t see any unique application of the photographer''s talents here.', '2010-02-02 00:20:04.000000', NULL, 1),
(5848525, 849811, 105441, '<td valign="top">Pretty good, but I''d like the rails and their vanishing point to be more prominent, probably by taking the photo from a point to the right and farther back.</td>', 'Pretty good, but I''d like the rails and their vanishing point to be more prominent, probably by taking the photo from a point to the right and farther back.', '2010-02-02 00:21:28.000000', NULL, 1),
