(5848754, 849579, 113075, '<td valign="top">Great graffiti, well captured!</td>', 'Great graffiti, well captured!', '2010-02-02 07:45:19.000000', NULL, 1),
(5848953, 850108, 61961, '<td valign="top">What to make of this?  One of the better/best photos in the challenge, but too far of a reach to connect it to graffiti.  (No vote for now.)</td>', 'What to make of this?  One of the better/best photos in the challenge, but too far of a reach to connect it to graffiti.  (No vote for now.)', '2010-02-02 11:38:07.000000', NULL, 1),
